Viele moderne Webseiten (insbesondere mit AJAX-Paginierung oder Single-Page-Application-Ansätzen) ändern die URL mit history.pushState oder history.replaceState, ohne dass window.location.search oder window.location.pathname sofort aktualisiert werden – oder sie ändern die Inhalte, bevor die URL tatsächlich angepasst ist. Außerdem kann es sein, dass das setTargeting(false) nicht korrekt ausgelöst wird, wenn die Seite dynamisch nachlädt.

### Lösung: Auf Popstate- und PushState-Ereignisse hören

Du solltest neben dem Intervall auch auf das popstate-Event und ggf. auf eigene pushState/replaceState-Events reagieren. Da pushState/replaceState keine nativen Events auslösen, kann man sie patchen, um eigene Events zu feuern.

Hier ein robustes Beispiel, das sowohl Intervall als auch Events nutzt:

```javascript
(function () {
    let lastTargetingState = null;

    function checkTargeting() {
        const params = new URLSearchParams(window.location.search);
        const page = params.get("tx_solr[page]");
        const shouldBeTargeted =
            window.location.pathname === "/produkte/" &&
            (page === null || page === "1");

        if (shouldBeTargeted !== lastTargetingState) {
            lastTargetingState = shouldBeTargeted;
            setTargeting(shouldBeTargeted);
        }
    }

    // Patch pushState und replaceState, um ein Event zu feuern
    function patchHistoryMethod(type) {
        const orig = history[type];
        history[type] = function () {
            const rv = orig.apply(this, arguments);
            window.dispatchEvent(new Event(type));
            return rv;
        };
