    patchHistoryMethod('pushState');
    patchHistoryMethod('replaceState');

    // Events für URL-Änderungen
    window.addEventListener('popstate', checkTargeting);
    window.addEventListener('pushState', checkTargeting);
    window.addEventListener('replaceState', checkTargeting);

    // Initial prüfen
    checkTargeting();

    // Fallback: Intervall für seltene Fälle
    setInterval(checkTargeting, 500);
})();
```

