// Fonction utilitaire pour lire/écrire dans le localStorage
function getLastDisplayDate() {
  return localStorage.getItem('hariboWheelLastDisplayDate');
}
function setLastDisplayDate(date) {
  localStorage.setItem('hariboWheelLastDisplayDate', date);
}

// Vérifie si le visiteur a déjà cliqué sur JE JOUE !
var hasClicked = Kameleoon.API.Data.readCustomData('hasClickedJeJoue');

// Si le visiteur a déjà cliqué, on vérifie le capping
if (hasClicked) {
  var today = new Date().toISOString().slice(0, 10);
  var lastDisplay = getLastDisplayDate();

  if (lastDisplay === today) {
    // Déjà affiché aujourd'hui, on ne montre pas la pop-in
    return;
  } else {
    // On affiche la pop-in et on enregistre la date
    setLastDisplayDate(today);
  }
}

// Si le visiteur n'a jamais cliqué, on affiche la pop-in sans capping
// (le reste de ton code continue normalement)
```

