if (!visitedPages) {
    visitedPages = [];
} else {
    visitedPages = JSON.parse(visitedPages);
}

if (visitedPages.indexOf(currentUrl) === -1) {
    visitedPages.push(currentUrl);
    Kameleoon.API.Data.setCustomData('VisitedPages', JSON.stringify(visitedPages));
    Kameleoon.API.Data.setCustomData('ListPageCounter', visitedPages.length);
}
```

